using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        AssetDatabase.ImportAsset("Assets/Resources/HUDTree/Fonts/HomesteaderHUD.ttf", ImportAssetOptions.ForceUpdate);
        AssetDatabase.ImportAsset("Assets/Resources/HUDTree/Fonts/HomesteaderHUD_Medium.ttf", ImportAssetOptions.ForceUpdate);
        AssetDatabase.ImportAsset("Assets/Resources/HUDTree/Fonts/HomesteaderHUD_Bold.ttf", ImportAssetOptions.ForceUpdate);
        AssetDatabase.ImportAsset("Assets/Resources/HUDTree/Fonts/HomesteaderHUD_Italic.ttf", ImportAssetOptions.ForceUpdate);
        AssetDatabase.ImportAsset("Assets/Resources/HUDTree/Fonts/HomesteaderHUD_BoldItalic.ttf", ImportAssetOptions.ForceUpdate);
        AssetDatabase.SaveAssets();
        result.Log("Forced import on 5 TTFs.");
    }
}
